<article class="product-card" data-product-category="{{ $product['category'] }}" data-product-title="{{ $product['title'] }} {{ $product['brand'] }}" data-product-price="{{ $product['price'] }}" data-in-stock="true" data-on-sale="true">
    <a class="product-visual {{ $product['icon'] }}" href="{{ route('product.show', ['product' => $product['id']]) }}" aria-label="View {{ $product['title'] }}"><span class="product-badge">{{ $product['badge'] }}</span><span class="product-badge warranty">Official warranty</span><span class="product-icon">{{ $product['icon'] }}</span></a>
    <div class="product-body"><span class="product-brand">{{ $product['brand'] }}</span><a class="product-title" href="{{ route('product.show', ['product' => $product['id']]) }}">{{ $product['title'] }}</a><div class="product-rating"><span class="material-symbols-outlined">star</span><strong>{{ $product['rating'] }}</strong><small>({{ $product['reviews'] }})</small></div><div class="product-price"><strong>Rs. {{ number_format($product['price']) }}</strong><del>Rs. {{ number_format($product['old']) }}</del></div><div class="product-actions"><button class="button button-primary" type="button" data-add-cart data-id="{{ $product['id'] }}" data-title="{{ $product['title'] }}" data-price="{{ $product['price'] }}" data-icon="{{ $product['icon'] }}">Add</button><a class="button button-outline" href="{{ route('product.show', ['product' => $product['id']]) }}">Preview</a></div></div>
</article>